import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class JsoupTest {

    public static void main(String[] args) {
        String html = "<html><body>Hello World!</body></html>";
        Document doc = Jsoup.parse(html);

        // Find all paragraph elements on the webpage
        Element paragraphElement1 = doc.select("p").first();
        System.out.println(append(paragraphElement1.text(), paragraphElement1));
    }

    public static String append(String text, Element element) {
        return append(text, element.html());
    }
}
